INSERT INTO `contact_messages` (`id`, `user_id`, `nom`, `prenom`, `email`, `motif`, `message`, `reponse`, `statut`, `token`, `created_at`, `replied_at`) VALUES
(3, 5, 'VEYRET', 'Cyprien', 'cyprien.veyret@gmail.com', 'Renseignement séjour', 'Bonjour,\r\nPourriez vous me dire si', 'Veuillez Préciser svp', 'Traité', '01a430b16c43651074b06c7376a15c9939910e9efc6a24f4e5d47dc530afe44f', '2025-12-18 14:38:33', '2025-12-18 15:04:55'),
(4, 5, 'VEYRET', 'Cyprien', 'cyprien.veyret@gmail.com', 'Recrutement / Animation', 'je veut devenir directeur', 'Bonjours, vous pouvez devenir directeur en vous inscrivant ici https://moncamp.fr/profile', 'Traité', '7e7b949528d9cefe34cd851c8b49e9b22d5d9683cd59e364c4fe1bbe68a27d6d', '2025-12-18 14:40:25', '2025-12-18 14:46:33'),
(5, NULL, 'VEYRET', 'Cyprien', 'cypvdv@gmail.com', 'Inscription / Réservation', 'Test de mail', 'alors la mystère', 'Traité', '206c0af200791eecf880aa1bf96b41f8e9314df7b58920cfc6ddc4a5eb5be9e0', '2025-12-18 14:49:44', '2025-12-18 14:58:42'),
(6, 5, 'VEYRET', 'Cyprien', 'cyprien.veyret@gmail.com', 'Compte / Connexion', 'Je n&#039;arrive pas a me connecter a mon compte...', '<p data-start=\"243\" data-end=\"253\">Bonjour,</p>\r\n<p data-start=\"255\" data-end=\"433\">Nous sommes d&eacute;sol&eacute;s d&rsquo;apprendre que vous rencontrez des difficult&eacute;s pour vous connecter &agrave; votre compte. Voici quelques solutions qui peuvent vous aider &agrave; r&eacute;soudre ce probl&egrave;me :</p>\r\n<ol data-start=\"435\" data-end=\"1114\">\r\n<li data-start=\"435\" data-end=\"596\">\r\n<p data-start=\"438\" data-end=\"596\"><strong data-start=\"438\" data-end=\"467\">V&eacute;rifiez vos identifiants</strong><br data-start=\"467\" data-end=\"470\">Assurez-vous que l&rsquo;adresse e-mail et le mot de passe saisis sont corrects (attention aux majuscules, espaces et au clavier).</p>\r\n</li>\r\n<li data-start=\"598\" data-end=\"784\">\r\n<p data-start=\"601\" data-end=\"784\"><strong data-start=\"601\" data-end=\"637\">R&eacute;initialisez votre mot de passe</strong><br data-start=\"637\" data-end=\"640\">Si vous avez oubli&eacute; votre mot de passe, vous pouvez en cr&eacute;er un nouveau <strong data-start=\"712\" data-end=\"733\">(En <a href=\"forgot_password\">cliquant ici</a>)</strong>. Un e-mail de r&eacute;initialisation vous sera envoy&eacute;.</p>\r\n</li>\r\n<li data-start=\"786\" data-end=\"947\">\r\n<p data-start=\"789\" data-end=\"947\"><strong data-start=\"789\" data-end=\"820\">V&eacute;rifiez votre bo&icirc;te e-mail</strong><br data-start=\"820\" data-end=\"823\">Pensez &agrave; v&eacute;rifier vos spams ou courriers ind&eacute;sirables si vous ne recevez pas l&rsquo;e-mail de connexion ou de r&eacute;initialisation.</p>\r\n</li>\r\n<li data-start=\"949\" data-end=\"1114\">\r\n<p data-start=\"952\" data-end=\"1114\"><strong data-start=\"952\" data-end=\"1002\">Essayez depuis un autre navigateur ou appareil</strong><br data-start=\"1002\" data-end=\"1005\">Parfois, le probl&egrave;me peut venir du navigateur utilis&eacute;. Vous pouvez &eacute;galement vider le cache et les cookies.</p>\r\n</li>\r\n</ol>\r\n<p data-start=\"1116\" data-end=\"1386\">Si le probl&egrave;me persiste malgr&eacute; ces v&eacute;rifications, notre &eacute;quipe reste &agrave; votre disposition pour vous aider. Vous pouvez nous contacter directement <strong data-start=\"1261\" data-end=\"1282\">(<a href=\"contact\" target=\"_blank\" rel=\"noopener\">En cliquant ici</a>)</strong> en pr&eacute;cisant votre adresse e-mail de compte et, si possible, une capture d&rsquo;&eacute;cran du message d&rsquo;erreur.</p>\r\n<p data-start=\"1388\" data-end=\"1403\">Cordialement,</p>\r\n<p data-start=\"1405\" data-end=\"1427\"><strong data-start=\"1405\" data-end=\"1425\">L&rsquo;&eacute;quipe support</strong></p>', 'Traité', 'a4c919e594f10e6f568f80c5d30dc5353bca563cef3210312d9a09bea85a268d', '2025-12-18 15:04:30', '2025-12-18 15:21:52'),
(7, 5, 'VEYRET', 'Cyprien', 'cyprien.veyret@gmail.com', 'Compte / Connexion', 'het test', '<p>Tette de lien&nbsp;<a href=\"contact\">test</a></p>', 'Traité', '06cf350ac2a437ed17bbfbcf1bda585b6a8ba73e8b604247e7aa5a65a8d32e0d', '2025-12-18 15:23:58', '2025-12-18 15:24:35'),
(8, 5, 'VEYRET', 'Cyprien', 'cyprien.veyret@gmail.com', 'Compte / Connexion', 'Tets sans le mail', '<p data-start=\"243\" data-end=\"253\">Bonjour,</p>\r\n<p data-start=\"255\" data-end=\"433\">Nous sommes d&eacute;sol&eacute;s d&rsquo;apprendre que vous rencontrez des difficult&eacute;s pour vous connecter &agrave; votre compte. Voici quelques solutions qui peuvent vous aider &agrave; r&eacute;soudre ce probl&egrave;me :</p>\r\n<ol data-start=\"435\" data-end=\"1114\">\r\n<li data-start=\"435\" data-end=\"596\">\r\n<p data-start=\"438\" data-end=\"596\"><strong data-start=\"438\" data-end=\"467\">V&eacute;rifiez vos identifiants</strong><br data-start=\"467\" data-end=\"470\">Assurez-vous que l&rsquo;adresse e-mail et le mot de passe saisis sont corrects (attention aux majuscules, espaces et au clavier).</p>\r\n</li>\r\n<li data-start=\"598\" data-end=\"784\">\r\n<p data-start=\"601\" data-end=\"784\"><strong data-start=\"601\" data-end=\"637\">R&eacute;initialisez votre mot de passe</strong><br data-start=\"637\" data-end=\"640\">Si vous avez oubli&eacute; votre mot de passe, vous pouvez en cr&eacute;er un nouveau <strong data-start=\"712\" data-end=\"733\">(<a href=\"forget_paswords\">En cliquant ici</a>)</strong>. Un e-mail de r&eacute;initialisation vous sera envoy&eacute;.</p>\r\n</li>\r\n<li data-start=\"786\" data-end=\"947\">\r\n<p data-start=\"789\" data-end=\"947\"><strong data-start=\"789\" data-end=\"820\">V&eacute;rifiez votre bo&icirc;te e-mail</strong><br data-start=\"820\" data-end=\"823\">Pensez &agrave; v&eacute;rifier vos spams ou courriers ind&eacute;sirables si vous ne recevez pas l&rsquo;e-mail de connexion ou de r&eacute;initialisation.</p>\r\n</li>\r\n<li data-start=\"949\" data-end=\"1114\">\r\n<p data-start=\"952\" data-end=\"1114\"><strong data-start=\"952\" data-end=\"1002\">Essayez depuis un autre navigateur ou appareil</strong><br data-start=\"1002\" data-end=\"1005\">Parfois, le probl&egrave;me peut venir du navigateur utilis&eacute;. Vous pouvez &eacute;galement vider le cache et les cookies.</p>\r\n</li>\r\n</ol>\r\n<p data-start=\"1116\" data-end=\"1386\">Si le probl&egrave;me persiste malgr&eacute; ces v&eacute;rifications, notre &eacute;quipe reste &agrave; votre disposition pour vous aider. Vous pouvez nous contacter directement <strong data-start=\"1261\" data-end=\"1282\">(En cliquant ici)</strong> en pr&eacute;cisant votre adresse e-mail de compte et, si possible, une capture d&rsquo;&eacute;cran du message d&rsquo;erreur.</p>\r\n<p data-start=\"1388\" data-end=\"1403\">Cordialement,</p>\r\n<p data-start=\"1405\" data-end=\"1427\"><strong data-start=\"1405\" data-end=\"1425\">L&rsquo;&eacute;quipe support</strong></p>', 'Traité', '03336c8195b32adb6e81779d6ea4e785229ae1a44b16319bbecf6e320d6e4c57', '2025-12-18 15:31:04', '2025-12-18 15:32:57'),
